create type public.trust_review_status as enum('open','reviewing','upheld','adjusted','dismissed');create table public.trust_score_review_requests(id uuid primary key default gen_random_uuid(),player_id uuid not null references public.players,challenged_ledger_id uuid not null references private.trust_score_ledger,reason text not null,status public.trust_review_status not null default'open',assigned_admin_id uuid references auth.users,decision_reason text,decided_at timestamptz,decision_ledger_id uuid references private.trust_score_ledger,version bigint not null default 1,created_at timestamptz not null default now());create unique index trust_review_one_open_idx on public.trust_score_review_requests(challenged_ledger_id)where status in('open','reviewing');alter table public.trust_score_review_requests enable row level security;create policy trust_review_owner_or_admin on public.trust_score_review_requests for select to authenticated using(player_id=public.current_player_id()or public.is_platform_admin());grant select on public.trust_score_review_requests to authenticated;revoke insert,update,delete on public.trust_score_review_requests from authenticated;
create or replace function public.get_my_trust_score_history()returns table(id uuid,reason_code text,delta numeric,previous_score numeric,current_score numeric,created_at timestamptz)language sql stable security definer set search_path=pg_catalog,public,private as $$select l.id,l.reason_code,l.delta,l.previous_score,l.current_score,l.created_at from private.trust_score_ledger l where l.player_id=public.current_player_id()order by l.created_at desc$$;
create or replace function public.request_trust_score_review(p_ledger_entry_id uuid,p_reason text,p_idempotency_key uuid)returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v_id uuid;begin insert into public.trust_score_review_requests(player_id,challenged_ledger_id,reason)select public.current_player_id(),id,p_reason from private.trust_score_ledger where id=p_ledger_entry_id and player_id=public.current_player_id()and actor_auth_user_id is not null returning id into v_id;if v_id is null then raise exception using errcode='P0001',detail='PERMISSION_DENIED';end if;insert into private.audit_log(actor_auth_user_id,action,aggregate_type,aggregate_id,request_id)values(auth.uid(),'trust.review_requested','trust_review',v_id,p_idempotency_key);return v_id;end$$;
create or replace function public.decide_trust_score_review(p_review_id uuid,p_decision text,p_reason text,p_idempotency_key uuid)returns uuid language plpgsql security definer set search_path=pg_catalog,public,private as $$declare v public.trust_score_review_requests%rowtype;v_original private.trust_score_ledger%rowtype;v_new uuid;v_previous numeric;begin perform private.require_platform_admin();select*into v from public.trust_score_review_requests where id=p_review_id and status in('open','reviewing')for update;if v.id is null then raise exception using errcode='P0001',detail='INVALID_STATE_TRANSITION';end if;if p_decision='adjusted'then select*into v_original from private.trust_score_ledger where id=v.challenged_ledger_id;select current_score into v_previous from private.trust_score_ledger where player_id=v.player_id order by created_at desc limit 1;insert into private.trust_score_ledger(player_id,reason_code,delta,previous_score,current_score,source_id,actor_auth_user_id,rule_version,request_id)values(v.player_id,'review_compensation',-v_original.delta,v_previous,greatest(0,least(100,v_previous-v_original.delta)),v.id,auth.uid(),'trust-v1',p_idempotency_key)returning id into v_new;end if;update public.trust_score_review_requests set status=p_decision::public.trust_review_status,decision_reason=p_reason,assigned_admin_id=auth.uid(),decided_at=now(),decision_ledger_id=v_new,version=version+1 where id=v.id;return v_new;end$$;revoke all on function public.get_my_trust_score_history(),public.request_trust_score_review(uuid,text,uuid),public.decide_trust_score_review(uuid,text,text,uuid)from public;grant execute on function public.get_my_trust_score_history(),public.request_trust_score_review(uuid,text,uuid),public.decide_trust_score_review(uuid,text,text,uuid)to authenticated;
